SELECT id,name,sort_name,year,genre,cover_r2_key,song_count,duration,size,compilation FROM albums WHERE id IN('pending-uploads','al-ac89e8964d','al-q5-wav-alternate') ORDER BY id;
SELECT COUNT(*) count,COALESCE(SUM(sm.duration),0) duration,COALESCE(SUM(si.size),0) size FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id WHERE sm.album_id='pending-uploads';
SELECT sm.id master_id,sm.album_id,sm.artist_id,sm.album_artist_id,sm.title,sm.track,sm.disc,sm.duration master_duration,sm.lyrics IS NOT NULL has_lyrics,sm.lyrics_rich IS NOT NULL has_rich_lyrics,sm.cover_r2_key,si.id instance_id,si.source_id,si.source_type,si.storage_uri,si.suffix,si.size instance_size,si.duration instance_duration,si.missing,si.tag_scanned,si.storage_object_id,si.source_etag,se.id entry_id,se.source_id entry_source_id,se.parent_id,se.path,se.display_name,se.kind,se.object_id,se.companion_of,so.physical_key,so.legacy_key,so.size object_size,so.etag object_etag,so.suffix object_suffix,so.content_type FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_entries se ON se.instance_id=si.id JOIN storage_objects so ON so.id=si.storage_object_id WHERE sm.id IN('sm-upload-1c5e734b-599','486') ORDER BY sm.id;
SELECT g.id,g.display_name,m.album_id,m.sort_order FROM album_display_groups g LEFT JOIN album_display_group_members m ON m.group_id=g.id WHERE g.display_name='平行四界Quadimension 5' OR m.album_id='al-ac89e8964d' ORDER BY m.sort_order
